-- Schema drift closure, RLS policies part 2: public schema, tables a-o
-- (35 policies).
--
-- Policy DDL generated by the database from pg_policy, then md5-verified
-- against that generated text (184dc9b63dbc29a1ded0ae7127c8f57f). The
-- DROP POLICY IF EXISTS guards below are added for replayability and are not
-- part of the generated output; verification compares CREATE statements only.
--
-- This is where the storefront's actual access model lives. Three patterns
-- recur:
--
--   own-row access - addresses, carts, cart_items, favorites, notifications,
--   conversation_participants, event_reservations. Each is scoped to
--   auth.uid(). cart_items reaches through to carts and additionally requires
--   the cart to still be active, so items cannot be added to a converted or
--   abandoned cart.
--
--   time-bounded public read - campaigns and their targeting joins are visible
--   to anon only while status is active and now() falls inside the campaign
--   window. An expired or paused campaign disappears from the public API
--   automatically, with no scheduled job involved.
--
--   participant-scoped messaging - conversations and messages are readable
--   only by a row in conversation_participants. messages_insert_participant
--   additionally pins sender_user_id to the caller and restricts message_type
--   to text/image/file, so a client cannot forge a message from someone else
--   or inject a 'system' message.
--
-- Two deliberate denials worth noting: coupons carries a RESTRICTIVE deny, so
-- coupon rows - even the hashes - are unreachable from any client, and
-- order_status_history is filtered on visible_to_customer, so internal
-- operational notes never reach the customer timeline.
--
-- Applying is a no-op against the live project.

DROP POLICY IF EXISTS addresses_manage_own ON public.addresses;
CREATE POLICY addresses_manage_own ON public.addresses
  FOR ALL
  TO authenticated
  USING ((user_id = ( SELECT auth.uid() AS uid)))
  WITH CHECK ((user_id = ( SELECT auth.uid() AS uid)));

DROP POLICY IF EXISTS brand_settings_public_read ON public.brand_settings;
CREATE POLICY brand_settings_public_read ON public.brand_settings
  FOR SELECT
  TO anon, authenticated
  USING (true);

DROP POLICY IF EXISTS campaign_categories_admin_delete ON public.campaign_categories;
CREATE POLICY campaign_categories_admin_delete ON public.campaign_categories
  FOR DELETE
  TO authenticated
  USING (( SELECT private.is_admin() AS is_admin));

DROP POLICY IF EXISTS campaign_categories_admin_insert ON public.campaign_categories;
CREATE POLICY campaign_categories_admin_insert ON public.campaign_categories
  FOR INSERT
  TO authenticated
  WITH CHECK (( SELECT private.is_admin() AS is_admin));

DROP POLICY IF EXISTS campaign_categories_admin_update ON public.campaign_categories;
CREATE POLICY campaign_categories_admin_update ON public.campaign_categories
  FOR UPDATE
  TO authenticated
  USING (( SELECT private.is_admin() AS is_admin))
  WITH CHECK (( SELECT private.is_admin() AS is_admin));

DROP POLICY IF EXISTS campaign_categories_authenticated_read ON public.campaign_categories;
CREATE POLICY campaign_categories_authenticated_read ON public.campaign_categories
  FOR SELECT
  TO authenticated
  USING (((EXISTS ( SELECT 1
   FROM campaigns campaign
  WHERE ((campaign.id = campaign_categories.campaign_id) AND (campaign.status = 'active'::text) AND ((timezone('utc'::text, now()) >= campaign.starts_at) AND (timezone('utc'::text, now()) <= campaign.ends_at))))) OR ( SELECT private.is_admin() AS is_admin)));

DROP POLICY IF EXISTS campaign_categories_public_read ON public.campaign_categories;
CREATE POLICY campaign_categories_public_read ON public.campaign_categories
  FOR SELECT
  TO anon
  USING ((EXISTS ( SELECT 1
   FROM campaigns campaign
  WHERE ((campaign.id = campaign_categories.campaign_id) AND (campaign.status = 'active'::text) AND ((timezone('utc'::text, now()) >= campaign.starts_at) AND (timezone('utc'::text, now()) <= campaign.ends_at))))));

